def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    units = int(supply // WATER_REQ)
    if units < 0:
        units = 0

    serious_bids = []
    all_prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            all_prev_bids.append(float(pbid))
            if float(pbid) >= 80:
                serious_bids.append(float(pbid))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 300:
            if pbid is not None and float(pbid) >= 95:
                rich_aggressive += 1

    highest_prev = max(all_prev_bids) if all_prev_bids else 0.0
    high_anchor = max(102.0, highest_prev + 1.2)
    medium_anchor = max(72.0, min(96.0, highest_prev * 0.82 if highest_prev > 0 else 78.0))
    low_anchor = 24.0

    urgent = hp <= 3 or no_water >= 1
    very_urgent = hp <= 2 or no_water >= 2

    if not alive:
        bid = min(budget, 18.0 if not urgent else 45.0)
        return float(max(0.0, bid))

    if units >= 2:
        if very_urgent:
            bid = min(budget, medium_anchor)
        elif urgent:
            bid = min(budget, 58.0)
        else:
            bid = min(budget, low_anchor + 2.0 * desperate_count)
    elif units == 1:
        if very_urgent:
            bid = min(budget, high_anchor)
        elif urgent:
            bid = min(budget, max(88.0, medium_anchor + 8.0))
        else:
            if rich_aggressive >= 2:
                bid = min(budget, 34.0)
            else:
                bid = min(budget, medium_anchor)
    else:
        bid = 0.0

    if day >= 8 and hp >= 5 and no_water == 0 and units == 1 and rich_aggressive >= 1:
        bid = min(bid, 28.0)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 35.0
    if budget - bid < reserve_floor and not urgent:
        bid = max(0.0, budget - reserve_floor)

    if very_urgent:
        bid = max(bid, min(budget, 84.0 if units >= 2 else high_anchor))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], avg_opp_bid + 15.0)

    if day_context['supply'] < WATER_REQ * 2:
        return min(my_status['budget'], avg_opp_bid + 5.0)

    return min(my_status['budget'], max(40.0, avg_opp_bid * 0.9))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid: 60% of salary
    base_bid = 0.6 * DAILY_SALARY

    if my_status['hp'] <= 2:
        # Desperate: bid almost full salary or up to budget
        bid = min(my_status['budget'], 0.95 * DAILY_SALARY)
    else:
        if len(yesterday_bids) > 0:
            avg_prev = sum(yesterday_bids) / len(yesterday_bids)
            if avg_prev > 90:
                # Opponents were aggressive: undercut a bit
                bid = min(my_status['budget'], max(base_bid, avg_prev * 0.85))
            else:
                bid = min(my_status['budget'], max(base_bid, avg_prev + 5))
        else:
            bid = min(my_status['budget'], base_bid)

    # Ensure we don't bid more than budget and not negative
    bid = max(0, min(bid, my_status['budget']))
    return bid
